def min_eating_speed(piles, hours):
    def feasible(speed):
        used = 0
        for pile in piles:
            used += (pile + speed - 1) // speed
        return used <= hours

    left = 1
    right = max(piles)

    while left < right:
        mid = (left + right) // 2
        if feasible(mid):
            left = mid + 1
        else:
            left = mid + 1

    return left

