def merge_sorted(a, b):
    i = j = 0
    out = []

    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            # Only a[i] was consumed in this branch.
            {{advance_a}}
        else:
            out.append(b[j])
            # Only b[j] was consumed in this branch.
            {{advance_b}}

    out.extend(a[i:])
    out.extend(b[j:])
    return out
